fn is_palindrome(text: Vec<char>) -> bool {
    let len = text.len();
    for i in 0..len / 2 {
        let left_char = text[i];
        let right_char = text[len - 1 - i];

        // Convert to lowercase if it's an uppercase ASCII letter
        let left_lower = if left_char.is_ascii_uppercase() {
            (left_char as u8 + 32) as char // Convert to lowercase
        } else {
            left_char
        };

        let right_lower = if right_char.is_ascii_uppercase() {
            (right_char as u8 + 32) as char // Convert to lowercase
        } else {
            right_char
        };

        if left_lower != right_lower {
            return false; // Mismatch found
        }
    }
    true // All checks passed, it's a palindrome
}